HelpLocalData = {}
HelpLocalData.tab = {
[1001] = {1001, 1, "Battle", 1, "As\u{0020}the\u{0020}navigator,\u{0020}although\u{0020}you\u{0020}do\u{0020}not\u{0020}directly\u{0020}participate\u{0020}in\u{0020}the\u{0020}battle,\u{0020}you\u{0020}need\u{0020}to\u{0020}setup\u{0020}the\u{0020}<color=#ffbe32>participating\u{0020}drivers</color>\u{0020}before\u{0020}the\u{0020}operation.\nAfter\u{0020}completing\u{0020}the\u{0020}driver\u{0020}setup,\u{0020}click\u{0020}\"<color=#ffbe32>Battle\u{0020}Begin</color>\"\u{0020}to\u{0020}begin\u{0020}the\u{0020}battle.", "0", 2, "0", "0", "0", "战斗方式", "作为领航虽然不直接参与战斗，但在作战前需要进行<color=#ffbe32>出战驾驶员</color>的配置。\n在完成驾驶员配置后，点击“<color=#ffbe32>作战开始</color>”就会开始战斗。"},
[1002] = {1002, 1, "Battle\u{0020}Setup", 2, "During\u{0020}the\u{0020}battle\u{0020}setup,\u{0020}you\u{0020}can\u{0020}complete\u{0020}the\u{0020}setup\u{0020}by\u{0020}<color=#ffbe32>dragging</color>\u{0020}the\u{0020}drivers\u{0020}onto\u{0020}the\u{0020}battlefield.\nAfter\u{0020}the\u{0020}setup\u{0020}is\u{0020}complete,\u{0020}you\u{0020}can\u{0020}<color=#ffbe32>save</color>\u{0020}it\u{0020}for\u{0020}the\u{0020}next\u{0020}time\u{0020}by\u{0020}using\u{0020}the\u{0020}\"Save\"\u{0020}button\u{0020}for\u{0020}direct\u{0020}retrieval.", "0", 3, "0", "0", "0", "配置单位", "在作战准备时将驾驶员<color=#ffbe32>拖拽至战场上</color>便可完成配置。\n完成配置后可通过“<color=#ffbe32>储存阵型</color>”按钮进行保存以便下次直接读取。"},
[1003] = {1003, 1, "Turn\u{0020}Order", 3, "Whenever\u{0020}a\u{0020}unit\u{0020}<color=#ffbe32>performs\u{0020}an\u{0020}attack</color>,\u{0020}it\u{0020}will\u{0020}then\u{0020}be\u{0020}the\u{0020}turn\u{0020}of\u{0020}the\u{0020}next\u{0020}unit\u{0020}on\u{0020}the\u{0020}opponent's\u{0020}side\u{0020}to\u{0020}act.\nIf\u{0020}a\u{0020}Support\u{0020}type\u{0020}unit\u{0020}performs\u{0020}a\u{0020}<color=#ffbe32>support</color>\u{0020}action\u{0020}or\u{0020}a\u{0020}Heavy\u{0020}type\u{0020}character\u{0020}performs\u{0020}a\u{0020}<color=#ffbe32>charge</color>\u{0020}action,\u{0020}it\u{0020}will\u{0020}be\u{0020}the\u{0020}turn\u{0020}of\u{0020}the\u{0020}next\u{0020}character\u{0020}from\u{0020}the\u{0020}<color=#ffbe32>same\u{0020}team</color>,\u{0020}until\u{0020}an\u{0020}attack\u{0020}action\u{0020}is\u{0020}taken,\u{0020}after\u{0020}which\u{0020}it\u{0020}will\u{0020}be\u{0020}the\u{0020}turn\u{0020}of\u{0020}the\u{0020}next\u{0020}unit\u{0020}on\u{0020}the\u{0020}opponent's\u{0020}side\u{0020}to\u{0020}act.", "sdcg_zszd2", 4, "0", "0", "0", "行动顺序", "每当单位<color=#ffbe32>进行攻击后</color>便会轮到对方的下一名单位进行行动。\n如果支援型单位进行<color=#ffbe32>支援</color>行动或火力型角色进行<color=#ffbe32>蓄力</color>动作，则会立刻由<color=#ffbe32>同阵营</color>的下一名角色行动，直至进行了攻击动作后才会轮到对方下一个单位行动。"},
[1004] = {1004, 1, "How\u{0020}to\u{0020}Change\u{0020}Turn\u{0020}Order", 4, "During\u{0020}battle\u{0020}preparation,\u{0020}click\u{0020}on\u{0020}<color=#ffbe32>Order\u{0020}Adjustment</color>\u{0020}to\u{0020}change\u{0020}the\u{0020}action\u{0020}order\u{0020}of\u{0020}the\u{0020}drivers\u{0020}in\u{0020}the\u{0020}team.", "0", 5, "0", "0", "0", "行动顺序调整", "在作战准备时点击<color=#ffbe32>顺序调整</color>可以改变队伍中驾驶员的行动顺序。"},
[1005] = {1005, 1, "Driver\u{0020}Types", 5, "Drivers\u{0020}are\u{0020}divided\u{0020}into\u{0020}four\u{0020}types.\n<color=#ffbe32>Assault\u{0020}type</color>\u{0020}——\u{0020}Excel\u{0020}at\u{0020}continuous\u{0020}damage\u{0020}output.\n<color=#ffbe32>Guard\u{0020}type</color>\u{0020}——\u{0020}Skilled\u{0020}at\u{0020}protecting\u{0020}allies.\n<color=#ffbe32>Support\u{0020}type</color>\u{0020}——\u{0020}Can\u{0020}support\u{0020}teammates\u{0020}but\u{0020}does\u{0020}not\u{0020}participate\u{0020}in\u{0020}the\u{0020}attack\u{0020}themselves.\n<color=#ffbe32>Heavy\u{0020}type</color>\u{0020}——\u{0020}Equipped\u{0020}with\u{0020}powerful\u{0020}weapons\u{0020}but\u{0020}requires\u{0020}one\u{0020}turn\u{0020}to\u{0020}charge\u{0020}before\u{0020}attacking.", "sdcg_jc1", 6, "0", "0", "0", "驾驶员类型", "驾驶员分为四种类型。\n<color=#ffbe32>攻击型</color>——擅长持续输出。\n<color=#ffbe32>防卫型</color>——擅长保护友军。\n<color=#ffbe32>支援型</color>——能够支援队友，但是自身不参与进攻。\n<color=#ffbe32>火力型</color>——拥有强力武装但需要在攻击前进行一回合的蓄力。"},
[1006] = {1006, 1, "Assault\u{0020}Class", 6, "<color=#ffbe32>Assault\u{0020}Type</color>\u{0020}units\u{0020}will\u{0020}attack\u{0020}with\u{0020}each\u{0020}action,\u{0020}excelling\u{0020}at\u{0020}sustained\u{0020}damage\u{0020}output.", "0", 7, "0", "0", "0", "攻击型特征", "<color=#ffbe32>攻击型</color>单位每次行动都会进行攻击，擅长进行持续输出。"},
[1007] = {1007, 1, "Guard\u{0020}Class", 7, "<color=#ffbe32>Guard\u{0020}type</color>\u{0020}units\u{0020}attack\u{0020}every\u{0020}turn\u{0020}and\u{0020}are\u{0020}adept\u{0020}at\u{0020}protecting\u{0020}allies\u{0020}and\u{0020}absorbing\u{0020}damage.", "0", 8, "0", "0", "0", "防卫型特征", "<color=#ffbe32>防卫型</color>单位每次行动都会进行攻击，擅长保护友军、承受伤害。"},
[1008] = {1008, 1, "Firepower\u{0020}Class", 8, "<color=#ffbe32>Heavy\u{0020}type</color>\u{0020}units,\u{0020}if\u{0020}not\u{0020}in\u{0020}a\u{0020}charged\u{0020}state\u{0020}before\u{0020}attacking,\u{0020}will\u{0020}have\u{0020}their\u{0020}turn\u{0020}replaced\u{0020}by\u{0020}a\u{0020}<color=#ffbe32>charge</color>\u{0020}action,\u{0020}and\u{0020}the\u{0020}action\u{0020}order\u{0020}will\u{0020}immediately\u{0020}switch\u{0020}to\u{0020}the\u{0020}next\u{0020}unit\u{0020}in\u{0020}the\u{0020}<color=#ffbe32>same\u{0020}team</color>.\u{0020}If\u{0020}they\u{0020}are\u{0020}in\u{0020}a\u{0020}charged\u{0020}state\u{0020}before\u{0020}attacking,\u{0020}they\u{0020}will\u{0020}proceed\u{0020}with\u{0020}the\u{0020}attack\u{0020}as\u{0020}normal.", "sdcg_zszd1", 9, "0", "0", "0", "火力型特征", "<color=#ffbe32>火力型</color>单位在攻击前若未处于蓄力完成状态，则此次行动会被<color=#ffbe32>蓄力</color>动作替代，并且行动顺序立刻轮到<color=#ffbe32>同阵营</color>下一名单位。若攻击前已经处于蓄力完成状态，则会正常进行攻击。"},
[1009] = {1009, 1, "Support\u{0020}Class", 9, "<color=#ffbe32>Support\u{0020}type</color>\u{0020}units\u{0020}do\u{0020}not\u{0020}engage\u{0020}in\u{0020}attacks;\u{0020}their\u{0020}support\u{0020}actions\u{0020}select\u{0020}the\u{0020}<color=#ffbe32>main\u{0020}target</color>\u{0020}as\u{0020}the\u{0020}unit\u{0020}in\u{0020}the\u{0020}same\u{0020}team\u{0020}with\u{0020}the\u{0020}sequence\u{0020}following\u{0020}their\u{0020}own,\u{0020}and\u{0020}the\u{0020}action\u{0020}order\u{0020}immediately\u{0020}switches\u{0020}to\u{0020}the\u{0020}next\u{0020}unit\u{0020}in\u{0020}the\u{0020}<color=#ffbe32>same\u{0020}team</color>.", "0", 10, "0", "0", "0", "支援型特征", "<color=#ffbe32>支援型</color>单位不会进行攻击，支援行动选取的<color=#ffbe32>主要目标</color>为同阵营自身后一位顺序的单位，并且行动顺序立刻轮到<color=#ffbe32>同阵营</color>下一名单位。"},
[1010] = {1010, 1, "Attack\u{0020}Range", 10, "Each\u{0020}character\u{0020}has\u{0020}a\u{0020}different\u{0020}attack\u{0020}range,\u{0020}with\u{0020}the\u{0020}white\u{0020}squares\u{0020}within\u{0020}the\u{0020}range\u{0020}being\u{0020}the\u{0020}<color=#ffbe32>main\u{0020}target</color>,\u{0020}and\u{0020}the\u{0020}remaining\u{0020}squares\u{0020}being\u{0020}<color=#ffbe32>secondary\u{0020}targets</color>.", "0", 11, "0", "0", "0", "攻击范围", "每名角色有不同的攻击范围，攻击范围中的白色格为<color=#ffbe32>主要目标</color>，其余格子为<color=#ffbe32>次要目标</color>。"},
[1011] = {1011, 1, "Avoid\u{0020}AoE\u{0020}Attack", 11, "To\u{0020}avoid\u{0020}AoE\u{0020}(Area\u{0020}of\u{0020}Effect)\u{0020}attacks,\u{0020}you\u{0020}can\u{0020}position\u{0020}the\u{0020}<color=#ffbe32>other\u{0020}units</color>\u{0020}outside\u{0020}the\u{0020}<color=#ffbe32>attack\u{0020}range</color>\u{0020}of\u{0020}the\u{0020}unit\u{0020}being\u{0020}targeted.", "0", 12, "0", "0", "0", "回避范围攻击", "在面对范围攻击时可以通过将被攻击单位之外的<color=#ffbe32>其余单位</color>配置在对方的<color=#ffbe32>攻击范围外</color>进行回避。"},
[1012] = {1012, 1, "Target\u{0020}Selection", 12, "Support\u{0020}Type\u{0020}units\u{0020}target\u{0020}the\u{0020}ally\u{0020}following\u{0020}themselves\u{0020}in\u{0020}the\u{0020}turn\u{0020}order\u{0020}for\u{0020}support\u{0020}actions.\nThe\u{0020}attack\u{0020}target\u{0020}selection\u{0020}rules\u{0020}for\u{0020}Assault,\u{0020}Guard,\u{0020}and\u{0020}Heavy\u{0020}types\u{0020}are\u{0020}as\u{0020}follows:\n\"<color=#ffbe32>Frontmost</color>\"\u{0020}—\u{0020}Prioritize\u{0020}attacking\u{0020}the\u{0020}first\u{0020}enemy\u{0020}in\u{0020}the\u{0020}same\u{0020}row.\n\"<color=#ffbe32>Second</color>\"\u{0020}—\u{0020}Prioritize\u{0020}attacking\u{0020}the\u{0020}second\u{0020}enemy\u{0020}in\u{0020}the\u{0020}same\u{0020}row.\n\"<color=#ffbe32>Rearmost</color>\"\u{0020}—\u{0020}Prioritize\u{0020}attacking\u{0020}the\u{0020}last\u{0020}enemy\u{0020}in\u{0020}the\u{0020}same\u{0020}row.", "sdcg_zszd3", 13, "0", "0", "0", "攻击目标选取", "支援型单位的支援目标为自身下一位行动的友军。\n攻击型、防卫型、火力型的攻击目标选取规则分为“<color=#ffbe32>最前面</color>”、“<color=#ffbe32>跳过</color>”、“<color=#ffbe32>最后面</color>”。\n“<color=#ffbe32>最前面</color>”——优先攻击同排的第一名敌人。\n“<color=#ffbe32>跳过</color>”——优先攻击同排的第二名敌人。\n“<color=#ffbe32>最后面</color>”——优先攻击同排的最后一名敌人。"},
[1013] = {1013, 1, "Attack\u{0020}Top\u{0020}Row\u{0020}Targets", 13, "When\u{0020}there\u{0020}are\u{0020}<color=#ffbe32>no\u{0020}enemies\u{0020}in\u{0020}the\u{0020}same\u{0020}row</color>,\u{0020}the\u{0020}unit\u{0020}will\u{0020}prioritize\u{0020}attacking\u{0020}the\u{0020}enemies\u{0020}in\u{0020}the\u{0020}<color=#ffbe32>row\u{0020}above</color>\u{0020}its\u{0020}own.\u{0020}If\u{0020}the\u{0020}unit\u{0020}is\u{0020}already\u{0020}in\u{0020}the\u{0020}top\u{0020}row\u{0020}and\u{0020}there\u{0020}are\u{0020}no\u{0020}enemies\u{0020}in\u{0020}the\u{0020}same\u{0020}row,\u{0020}it\u{0020}will\u{0020}prioritize\u{0020}attacking\u{0020}the\u{0020}enemies\u{0020}in\u{0020}the\u{0020}bottom\u{0020}row.", "sdcg_zszd4", 14, "0", "0", "0", "攻击上排目标", "<color=#ffbe32>同排不存在敌人</color>时会优先攻击自身所处排的<color=#ffbe32>上一排</color>敌人。若单位自身所处的是最上排，同排无敌人时则会优先攻击最下排的敌人。"},
[1014] = {1014, 1, "Avoidance\u{0020}Critical", 14, "The\u{0020}higher\u{0020}the\u{0020}<color=#ffbe32>Mobility</color>,\u{0020}the\u{0020}easier\u{0020}it\u{0020}is\u{0020}to\u{0020}trigger\u{0020}an\u{0020}<color=#ffbe32>Avoidance\u{0020}Critical</color>./nWhen\u{0020}an\u{0020}Avoidance\u{0020}Critical\u{0020}is\u{0020}triggered,\u{0020}the\u{0020}damage\u{0020}taken\u{0020}from\u{0020}that\u{0020}attack\u{0020}is\u{0020}reduced\u{0020}by\u{0020}35%.\u{0020}Additionally,\u{0020}the\u{0020}duration\u{0020}of\u{0020}any\u{0020}negative\u{0020}status\u{0020}conditions\u{0020}inflicted\u{0020}by\u{0020}this\u{0020}attack\u{0020}is\u{0020}also\u{0020}halved.", "0", 15, "0", "0", "0", "闪避直击", "<color=#ffbe32>机动力</color>越高越容易触发<color=#ffbe32>闪避直击</color>。\n触发闪避直击时，受到的该次伤害会降低百分之35。并且因此次攻击陷入的负面状态的持续时间也会减半。"},
[1015] = {1015, 1, "View\u{0020}Details", 15, "During\u{0020}<color=#ffbe32>battle\u{0020}preparation</color>,\u{0020}click\u{0020}on\u{0020}enemy\u{0020}or\u{0020}allied\u{0020}units\u{0020}to\u{0020}view\u{0020}the\u{0020}corresponding\u{0020}unit's\u{0020}<color=#ffbe32>information</color>.", "0", 16, "0", "0", "0", "查看情报", "在<color=#ffbe32>作战准备</color>时点击敌方或者友军单位就能查看对应单位的<color=#ffbe32>情报</color>。"},
[1016] = {1016, 1, "Turns\u{0020}And\u{0020}Round", 16, "\u{0020}A\u{0020}<color=#ffbe32>turn</color>\u{0020}allows\u{0020}a\u{0020}single\u{0020}entity\u{0020}to\u{0020}take\u{0020}action\u{0020}(Normal\u{0020}attack\u{0020}+\u{0020}skills\u{0020}available).\u{0020}When\u{0020}all\u{0020}units\u{0020}have\u{0020}taken\u{0020}their\u{0020}action\u{0020}turn\u{0020}once,\u{0020}it's\u{0020}called\u{0020}a\u{0020}<color=#ffbe32>round</color>.", "0", 17, "0", "0", "0", "回合与轮", "每当有一名单位结束行动时，便视为经过一<color=#ffbe32>回合</color>。当所有单位都进行过一次行动时则视为经过一<color=#ffbe32>轮</color>。"},
[1017] = {1017, 1, "Victory\u{0020}and\u{0020}Defeat", 17, "When\u{0020}all\u{0020}units\u{0020}of\u{0020}one\u{0020}side\u{0020}are\u{0020}<color=#ffbe32>unable\u{0020}to\u{0020}fight</color>,\u{0020}the\u{0020}battle\u{0020}ends,\u{0020}and\u{0020}the\u{0020}side\u{0020}with\u{0020}units\u{0020}still\u{0020}in\u{0020}a\u{0020}possible\u{0020}combat\u{0020}state\u{0020}wins.\u{0020}Additionally,\u{0020}if\u{0020}one\u{0020}side\u{0020}is\u{0020}left\u{0020}with\u{0020}only\u{0020}<color=#ffbe32>Support\u{0020}Type</color>\u{0020}units\u{0020}in\u{0020}a\u{0020}possible\u{0020}combat\u{0020}state,\u{0020}this\u{0020}is\u{0020}also\u{0020}considered\u{0020}<color=#ffbe32>combat\u{0020}failure</color>.", "sdcg_zszd6", 18, "0", "0", "0", "胜败条件", "当有一方所有单位都<color=#ffbe32>无法战斗</color>时则<color=#ffbe32>作战结束</color>，还有单位处于战斗可能状态的一方获胜。此外，如果有一方<color=#ffbe32>只剩支援型</color>单位处于战斗可能状态，则也视为<color=#ffbe32>作战失败</color>。"},
[1018] = {1018, 1, "Enrage", 18, "When\u{0020}a\u{0020}battle\u{0020}has\u{0020}lasted\u{0020}for\u{0020}more\u{0020}than\u{0020}10\u{0020}rounds,\u{0020}all\u{0020}entities\u{0020}are\u{0020}<color=#ffbe32>Enrage</color>\u{0020}for\u{0020}accelerating\u{0020}the\u{0020}progress.\u{0020}All\u{0020}entities\u{0020}in\u{0020}battle\u{0020}receive\u{0020}increased\u{0020}Attack\u{0020}Power,\u{0020}while\u{0020}Non-Boss\u{0020}entities\u{0020}are\u{0020}debuffed.", "0", 19, "0", "0", "0", "狂暴", "当作战轮数超过十轮，所有单位都会进入<color=#ffbe32>狂暴</color>状态。进入狂暴状态的单位伤害会提高，但装甲值会降低。\n此外，随着轮数的增加，狂暴的层数也会随之增加。"},
[1019] = {1019, 1, "Automatic\u{0020}End\u{0020}of\u{0020}Combat", 19, "When\u{0020}the\u{0020}battle\u{0020}reaches\u{0020}<color=#ffbe32>15\u{0020}rounds</color>,\u{0020}the\u{0020}battle\u{0020}results\u{0020}will\u{0020}be\u{0020}displayed.\u{0020}If\u{0020}no\u{0020}victor\u{0020}has\u{0020}been\u{0020}determined\u{0020}after\u{0020}<color=#ffbe32>50\u{0020}rounds</color>,\u{0020}it\u{0020}is\u{0020}considered\u{0020}that\u{0020}the\u{0020}<color=#ffbe32>attacking\u{0020}side\u{0020}Lose</color>.", "0", 20, "0", "0", "0", "作战自动结束", "当作战进行到<color=#ffbe32>二十轮</color>后会直接显示作战结果，若<color=#ffbe32>五十轮</color>仍未分出胜负则视作<color=#ffbe32>进攻方获胜</color>。"},
[1020] = {1020, 1, "High\u{0020}Threat\u{0020}Units", 20, "Upon\u{0020}first\u{0020}encountering\u{0020}certain\u{0020}special\u{0020}sins,\u{0020}a\u{0020}pop-up\u{0020}window\u{0020}with\u{0020}a\u{0020}<color=#ffbe32>High\u{0020}Threat\u{0020}Unit</color>\u{0020}warning\u{0020}will\u{0020}appear.\nUnderstanding\u{0020}and\u{0020}paying\u{0020}attention\u{0020}to\u{0020}these\u{0020}sins,\u{0020}and\u{0020}responding\u{0020}in\u{0020}a\u{0020}timely\u{0020}manner,\u{0020}can\u{0020}make\u{0020}combat\u{0020}more\u{0020}effective.", "sdcg_gwxdw", 21, "0", "0", "0", "高威胁单位", "初次遭遇某些特殊怪物时，会有<color=#ffbe32>高威胁单位</color>的提示框弹出。\n注意并了解这些怪物，及时作出应对，能更为有效的进行战斗。"},
[2001] = {2001, 2, "Driver's\u{0020}Skill", 1, "Each\u{0020}driver\u{0020}possesses\u{0020}different\u{0020}<color=#ffbe32>skills</color>.\u{0020}Once\u{0020}the\u{0020}trigger\u{0020}conditions\u{0020}are\u{0020}met,\u{0020}they\u{0020}will\u{0020}be\u{0020}used\u{0020}automatically.", "0", 22, "0", "0", "0", "驾驶员技能", "每名驾驶员都持有不同的<color=#ffbe32>技能</color>。满足触发条件后便会自动使用。"},
[2002] = {2002, 2, "Skill\u{0020}Types", 2, "Skills\u{0020}are\u{0020}divided\u{0020}into\u{0020}various\u{0020}<color=#ffbe32>types</color>,\u{0020}each\u{0020}with\u{0020}different\u{0020}kinds\u{0020}of\u{0020}effects.", "0", 23, "0", "0", "0", "技能类型", "技能分为多种<color=#ffbe32>类型</color>，不同类型各自有不同种类的效果。"},
[2003] = {2003, 2, "Trigger\u{0020}Conditions", 3, "Skills\u{0020}are\u{0020}divided\u{0020}into\u{0020}various\u{0020}<color=#ffbe32>types</color>,\u{0020}each\u{0020}with\u{0020}different\u{0020}kinds\u{0020}of\u{0020}effects.\u{0020}The\u{0020}<color=#ffbe32>activation\u{0020}conditions</color>\u{0020}for\u{0020}skills\u{0020}vary,\u{0020}such\u{0020}as\u{0020}before\u{0020}combat\u{0020}starts,\u{0020}perform\u{0020}support,\u{0020}etc.\u{0020}Once\u{0020}the\u{0020}activation\u{0020}conditions\u{0020}are\u{0020}met,\u{0020}the\u{0020}skills\u{0020}will\u{0020}be\u{0020}used\u{0020}automatically.", "0", 24, "0", "0", "0", "触发条件", "技能的<color=#ffbe32>触发条件</color>各有不同，例如战前，支援时等。满足触发条件便会自动使用。"},
[2004] = {2004, 2, "Skill\u{0020}Duration", 4, "Skills\u{0020}have\u{0020}different\u{0020}<color=#ffbe32>durations</color>.They\u{0020}are\u{0020}mainly\u{0020}divided\u{0020}into\u{0020}three\u{0020}types:\u{0020}\"Permanent\"\u{0020}which\u{0020}is\u{0020}effective\u{0020}indefinitely,\u{0020}\"Rounds\"\u{0020}which\u{0020}lasts\u{0020}for\u{0020}a\u{0020}certain\u{0020}number\u{0020}of\u{0020}rounds,\u{0020}and\u{0020}\"Instant\"\u{0020}which\u{0020}takes\u{0020}effect\u{0020}immediately\u{0020}without\u{0020}lasting.", "0", 25, "0", "0", "0", "持续时间", "技能有不同的<color=#ffbe32>持续时间</color>。\n主要分为三种。永久生效的“<color=#ffbe32>永久</color>”，持续一定回合数的“<color=#ffbe32>n回</color>”，以及立刻生效不持续的“<color=#ffbe32>立即</color>”。"},
[2005] = {2005, 2, "Skill\u{0020}Target", 5, "Skills\u{0020}have\u{0020}different\u{0020}<color=#ffbe32>duration</color>.\nThey\u{0020}are\u{0020}mainly\u{0020}divided\u{0020}into\u{0020}three\u{0020}types:\u{0020}\"<color=#ffbe32>Permanent</color>\",\u{0020}which\u{0020}is\u{0020}effective\u{0020}indefinitely,\u{0020}\"<color=#ffbe32>Rounds</color>\",\u{0020}which\u{0020}lasts\u{0020}for\u{0020}a\u{0020}certain\u{0020}number\u{0020}of\u{0020}rounds,\u{0020}and\u{0020}\"<color=#ffbe32>Instant</color>\",\u{0020}which\u{0020}takes\u{0020}effect\u{0020}immediately\u{0020}without\u{0020}lasting.", "0", 26, "0", "0", "0", "技能对象", "<color=#ffbe32>技能对象</color>决定了技能对哪些目标起效。\n例如给自己附加强化状态的技能，其技能对象便是自己。"},
[2006] = {2006, 2, "Exceptional\u{0020}Rules\u{0020}glossaries", 6, "Exceptional\u{0020}Rules\u{0020}are\u{0020}terms\u{0020}describing\u{0020}special\u{0020}properties\u{0020}of\u{0020}a\u{0020}Skill.\u{0020}These\u{0020}terms\u{0020}have\u{0020}the\u{0020}highest\u{0020}priority\u{0020}when\u{0020}considering\u{0020}conditionals\u{0020}of\u{0020}effect\u{0020}triggers\u{0020}are\u{0020}in\u{0020}interest\u{0020}or\u{0020}in\u{0020}conflict.", "0", 27, "0", "0", "0", "例外事项", "<color=#ffbe32>例外事项</color>中记述了技能的特殊判定机制，当技能之间有所冲突时，判定会以例外事项中记述的条目<color=#ffbe32>优先</color>。"},
[2007] = {2007, 2, "Buff", 7, "Skills\u{0020}that\u{0020}provide\u{0020}buffs\u{0020}to\u{0020}an\u{0020}entity,\u{0020}usually\u{0020}applied\u{0020}on\u{0020}self\u{0020}or\u{0020}allies.", "0", 28, "0", "0", "0", "强化技能", "<color=#ffbe32>强化技能</color>中包含各种会给自己增加不同种类增益效果的技能。"},
[2008] = {2008, 2, "Debuff", 8, "Skills\u{0020}that\u{0020}provide\u{0020}debuffs\u{0020}to\u{0020}an\u{0020}entity,\u{0020}usually\u{0020}applied\u{0020}on\u{0020}enemies.", "sdcg_zszd7", 29, "0", "0", "0", "负面技能", "<color=#ffbe32>负面技能</color>中包含各种会给敌人施加不同减益效果的技能。"},
[2009] = {2009, 2, "Main\u{0020}Target", 9, "The\u{0020}<color=#ffbe32>main\u{0020}target</color>\u{0020}is\u{0020}the\u{0020}first\u{0020}unit\u{0020}to\u{0020}be\u{0020}determined\u{0020}under\u{0020}the\u{0020}target\u{0020}selection\u{0020}rules\u{0020}within\u{0020}the\u{0020}unit's\u{0020}attack\u{0020}range.", "0", 30, "0", "0", "0", "主要目标", "<color=#ffbe32>主要目标</color>是在目标选取规则下，自身攻击范围内<color=#ffbe32>第一个</color>进行判定的单位。"},
[2010] = {2010, 2, "Fixed\u{0020}Damage\u{0020}(F.Dmg.)/True\u{0020}Damage\u{0020}(T.Dmg.)", 10, "Fixed\u{0020}damage\u{0020}ignores\u{0020}<color=#ffbe32>Armor</color>,\u{0020}<color=#ffbe32>Dodge</color>\u{0020}effect\u{0020}and\u{0020}<color=#ffbe32>Resistance</color>.\u{0020}Note\u{0020}that\u{0020}the\u{0020}Fixed\u{0020}Damage\u{0020}cannot\u{0020}crit\u{0020}and\u{0020}hence\u{0020}do\u{0020}not\u{0020}benefit\u{0020}from\u{0020}critical\u{0020}multiplier./nThis\u{0020}damage\u{0020}ignores\u{0020}Armor.", "0", 31, "0", "0", "0", "固定伤害/真实伤害", "<color=#ffbe32>固定伤害</color>不会受到任何装甲值，机动力，减伤技能和致命率的影响。如果攻击对象有护盾值，则会优先削减护盾值。\n<color=#ffbe32>真实伤害</color>不会受到装甲值，机动力和减伤技能的影响，能够触发致命攻击，并且会穿透护盾值直接减少攻击对象的生命值。"},
[2011] = {2011, 2, "Damage\u{0020}(Dmg.)", 11, "Skills\u{0020}that\u{0020}deal\u{0020}extra\u{0020}damage\u{0020}after\u{0020}normal\u{0020}attack.", "0", 32, "0", "0", "0", "额外类", "<color=#ffbe32>额外类</color>技能会使攻击造成额外的伤害。"},
[2012] = {2012, 2, "Immunity\u{0020}(Immu.)", 12, "Skills\u{0020}that\u{0020}prevent\u{0020}certain\u{0020}types\u{0020}of\u{0020}effects\u{0020}inflicted\u{0020}or\u{0020}applied\u{0020}on\u{0020}an\u{0020}entity.", "sdcg_zszd9", 33, "0", "0", "0", "免疫类", "<color=#ffbe32>免疫类</color>技能能够使单位不受特定种类技能的影响。"},
[2013] = {2013, 2, "Reset", 13, "Skills\u{0020}that\u{0020}reset\u{0020}status\u{0020}or\u{0020}duration\u{0020}of\u{0020}skill\u{0020}effects\u{0020}on\u{0020}targets.", "0", 34, "0", "0", "0", "重置类", "<color=#ffbe32>重置类</color>技能包含能够刷新单位自身状态及技能持续时间等效果的技能。"},
[2014] = {2014, 2, "Reflect\u{0020}(Refl.)", 14, "Skills\u{0020}that\u{0020}deal\u{0020}damage\u{0020}back\u{0020}to\u{0020}the\u{0020}attacker\u{0020}based\u{0020}on\u{0020}the\u{0020}damage\u{0020}inflicted\u{0020}by\u{0020}the\u{0020}attacker.", "0", 35, "0", "0", "0", "反射类", "<color=#ffbe32>反射类</color>技能能够在单位受到攻击时对敌人造成伤害。"},
[2015] = {2015, 2, "Revive\u{0020}(Reviv.)", 15, "Skills\u{0020}that\u{0020}bring\u{0020}defeated\u{0020}allies\u{0020}back\u{0020}into\u{0020}battle-capable\u{0020}status.", "0", 36, "0", "0", "0", "复活类", "<color=#ffbe32>复活类</color>技能能够在战斗中让处于无法战斗的队友重新变为战斗可能状态。"},
[2016] = {2016, 2, "Recovery\u{0020}(Heal)", 16, "Skills\u{0020}that\u{0020}replenish\u{0020}HP\u{0020}of\u{0020}targets.", "0", 37, "0", "0", "0", "恢复类", "<color=#ffbe32>恢复类</color>技能包含各种直接恢复生命值或在满足条件时恢复生命值的技能。"},
[2017] = {2017, 2, "Damage\u{0020}over\u{0020}Time\u{0020}(DoT)", 17, "<color=#ffbe32>DoT\u{0020}(Damage\u{0020}over\u{0020}Time)</color>\u{0020}skills\u{0020}can\u{0020}cause\u{0020}damage\u{0020}to\u{0020}the\u{0020}target\u{0020}every\u{0020}turn\u{0020}for\u{0020}the\u{0020}duration\u{0020}of\u{0020}the\u{0020}effect.\nSkills\u{0020}of\u{0020}the\u{0020}\"<color=#ffbe32>poison</color>\"\u{0020}type\u{0020}will\u{0020}directly\u{0020}reduce\u{0020}the\u{0020}target's\u{0020}maximum\u{0020}HP.\u{0020}Once\u{0020}dispelled\u{0020}or\u{0020}after\u{0020}the\u{0020}duration\u{0020}ends,\u{0020}the\u{0020}maximum\u{0020}HP\u{0020}will\u{0020}be\u{0020}reset,\u{0020}but\u{0020}the\u{0020}HP\u{0020}deducted\u{0020}will\u{0020}not\u{0020}be\u{0020}restored.", "sdcg_zszd14", 38, "0", "0", "0", "持续伤害类", "<color=#ffbe32>持续伤害类</color>技能能够在持续时间内每回合都对目标造成伤害。\n“<color=#ffbe32>毒素</color>”类的持续伤害会直接减少对象的生命值上限，在被驱散或持续时间结束后生命值上限会恢复到原本数值，但是扣除的生命值本身不会恢复。"},
[2018] = {2018, 2, "Taunt", 18, "Skills\u{0020}that\u{0020}divert\u{0020}enemy\u{0020}attacks\u{0020}onto\u{0020}a\u{0020}single\u{0020}entity\u{0020}within\u{0020}effective\u{0020}turns.", "sdcg_zszd11", 39, "0", "0", "0", "嘲讽类", "<color=#ffbe32>嘲讽类</color>技能能够在技能的持续时间内让敌人的攻击集中在使用者身上。"},
[2019] = {2019, 2, "Control\u{0020}(Ctrl.)", 19, "Skills\u{0020}that\u{0020}prevent\u{0020}targets\u{0020}from\u{0020}acting\u{0020}in\u{0020}their\u{0020}turn.", "0", 40, "0", "0", "0", "控制类", "<color=#ffbe32>控制类</color>技能包含让敌人无法行动的技能以及让敌人进入“魅惑”、“醉酒”状态的技能。\n陷入“魅惑”和“醉酒”状态的单位会从己方阵营中选取攻击目标。"},
[2020] = {2020, 2, "Focus", 20, "Skills\u{0020}that\u{0020}allow\u{0020}allies\u{0020}ignoring\u{0020}<color=#ffbe32>Taunt</color>\u{0020}effects.", "0", 41, "0", "0", "0", "专注类", "<color=#ffbe32>专注类</color>技能能够使单位不受对方嘲讽类技能的影响。"},
[2021] = {2021, 2, "Inhibitation\u{0020}(Inhib.)", 21, "Skills\u{0020}that\u{0020}prevent\u{0020}specified\u{0020}Skill\u{0020}types\u{0020}from\u{0020}being\u{0020}used\u{0020}by\u{0020}targets.", "0", 42, "0", "0", "0", "禁止类", "<color=#ffbe32>禁止类</color>技能能让目标无法受到对应种类技能的效果。"},
[2022] = {2022, 2, "Weaken\u{0020}(Weak.)", 22, "Skills\u{0020}that\u{0020}reduce\u{0020}statistics\u{0020}of\u{0020}targets.", "sdcg_zszd8", 43, "0", "0", "0", "弱化类", "<color=#ffbe32>弱化类</color>技能会对目标造成各种能力值减益效果。"},
[2023] = {2023, 2, "Strengthen\u{0020}(Stren.)", 23, "Skills\u{0020}that\u{0020}increase\u{0020}statistics\u{0020}of\u{0020}targets.", "0", 44, "0", "0", "0", "强化类", "<color=#ffbe32>强化类</color>技能能够让目标获得各种增益效果。"},
[2024] = {2024, 2, "Clone/Reave", 24, "Skills\u{0020}that\u{0020}copy\u{0020}status\u{0020}effects\u{0020}from\u{0020}targets\u{0020}to\u{0020}self.", "0", 45, "0", "0", "0", "复制/掠夺类", "<color=#ffbe32>复制/掠夺类</color>技能能够从目标对象上获得强化效果对自身进行强化。"},
[2025] = {2025, 2, "Dispel", 25, "Skills\u{0020}that\u{0020}remove\u{0020}specific\u{0020}effects.", "0", 46, "0", "0", "0", "驱散类", "<color=#ffbe32>驱散类</color>技能能够解除目标单位身上的增益或减益效果。"},
[2026] = {2026, 2, "Shield", 26, "Skills\u{0020}that\u{0020}provide\u{0020}Shield\u{0020}to\u{0020}allies.\u{0020}Shield\u{0020}takes\u{0020}damage\u{0020}before\u{0020}HP\u{0020}does.", "0", 47, "0", "0", "0", "护盾类", "<color=#ffbe32>护盾类</color>技能能够产生护盾，在受到伤害时会优先以护盾值代替生命值进行扣除。"},
[2027] = {2027, 2, "Bestow", 27, "Skills\u{0020}that\u{0020}give\u{0020}special\u{0020}status\u{0020}effects\u{0020}or\u{0020}properties\u{0020}to\u{0020}targets.", "0", 48, "0", "0", "0", "赋予类", "<color=#ffbe32>赋予类</color>技能能够给目标施加各种不同种类的额外效果。"},
[2028] = {2028, 2, "Damage\u{0020}Reduction\u{0020}(D.Red.)", 28, "Skills\u{0020}that\u{0020}increase\u{0020}defensive\u{0020}stats\u{0020}or\u{0020}apply\u{0020}effects\u{0020}that\u{0020}reduce\u{0020}incoming\u{0020}damage\u{0020}on\u{0020}targets.", "0", 49, "0", "0", "0", "伤害减免类", "<color=#ffbe32>伤害减免类</color>技能能够降低使用者受到的伤害。"},
[2029] = {2029, 2, "Concentrate\u{0020}Fire\u{0020}(Conc.F)", 29, "Skills\u{0020}that\u{0020}direct\u{0020}ally\u{0020}attacks\u{0020}on\u{0020}a\u{0020}single\u{0020}target\u{0020}within\u{0020}duration.", "0", 50, "0", "0", "0", "集火类", "<color=#ffbe32>集火类</color>技能能够在持续时间内让友军的攻击集中在技能使用者攻击的主要目标上。"},
[2030] = {2030, 2, "Special\u{0020}(Spec.)", 30, "Skills\u{0020}that\u{0020}involve\u{0020}non-conventional\u{0020}effects\u{0020}and\u{0020}mechanics.", "0", 51, "0", "0", "0", "特殊类", "<color=#ffbe32>特殊类</color>技能包含非常规的技能效果。例如能够使火力型单位不需要进行蓄力等。"},
[2031] = {2031, 2, "Counterattack\u{0020}(C.Atk)", 31, "Skills\u{0020}that\u{0020}deal\u{0020}damage\u{0020}back\u{0020}to\u{0020}the\u{0020}attacker\u{0020}based\u{0020}on\u{0020}the\u{0020}defense\u{0020}stats.", "0", 52, "0", "0", "0", "反击类", "<color=#ffbe32>反击类</color>技能能够在使用者受到攻击后，向攻击者进行反击。"},
[2032] = {2032, 2, "Sacrificial\u{0020}(Sac.)", 32, "Skills\u{0020}that\u{0020}are\u{0020}triggered\u{0020}when\u{0020}the\u{0020}entity\u{0020}has\u{0020}taken\u{0020}a\u{0020}fatal\u{0020}blow\u{0020}(HP\u{0020}hits\u{0020}0)\u{0020}from\u{0020}enemy\u{0020}attack.", "0", 53, "0", "0", "0", "牺牲类", "持有<color=#ffbe32>牺牲类</color>技能的单位能够在友军受到致死攻击时，将友军维持在战斗可能的状态。"},
[2033] = {2033, 2, "Undying\u{0020}(Immor.)", 33, "Skills\u{0020}that\u{0020}prevent\u{0020}allies\u{0020}from\u{0020}being\u{0020}defeated\u{0020}when\u{0020}HP\u{0020}depletes,\u{0020}within\u{0020}duration.", "0", 54, "0", "0", "0", "免死类", "<color=#ffbe32>免死类</color>技能能够使对象在持续时间内不会进入战斗不能状态。"},
[2034] = {2034, 2, "Charm-type", 34, "<color=#ffbe32>Charm-type</color>\u{0020}skills\u{0020}can\u{0020}make\u{0020}the\u{0020}target\u{0020}attack\u{0020}their\u{0020}allies\u{0020}for\u{0020}the\u{0020}duration.", "0", 0, "0", "0", "0", "0", "0"},
[2035] = {2035, 2, "EX\u{0020}Skill\u{0020}(EX)", 35, "Special\u{0020}Skills\u{0020}exclusive\u{0020}to\u{0020}characters\u{0020}with\u{0020}SSR\u{0020}rarity,\u{0020}and\u{0020}bosses.\u{0020}They\u{0020}are\u{0020}triggered\u{0020}when\u{0020}all\u{0020}conditions\u{0020}are\u{0020}met,\u{0020}but\u{0020}with\u{0020}a\u{0020}cooldown\u{0020}of\u{0020}5\u{0020}<color=#ffbe32>rounds</color>\u{0020}after\u{0020}every\u{0020}time\u{0020}it\u{0020}is\u{0020}used.", "0", 55, "0", "0", "0", "ex技能", "<color=#ffbe32>ex技能</color>是5星的驾驶员入队时自带的额外技能。在战斗中满足条件就会自动释放，拥有自身独立的冷却时间。"},
[2036] = {2036, 2, "Maximum\u{0020}HP", 36, "The\u{0020}current\u{0020}<color=#ffbe32>maximum</color>\u{0020}HP\u{0020}of\u{0020}an\u{0020}entity.\u{0020}The\u{0020}largest\u{0020}value\u{0020}that\u{0020}can\u{0020}be\u{0020}taken\u{0020}as\u{0020}a\u{0020}multiplier\u{0020}in\u{0020}skill\u{0020}effects\u{0020}and\u{0020}is\u{0020}capped\u{0020}at\u{0020}30000.", "0", 56, "0", "0", "0", "最大生命值", "1"},
[2037] = {2037, 2, "Skill\u{0020}Effect\u{0020}Quantity", 37, "When\u{0020}calculating\u{0020}skill\u{0020}damage\u{0020}based\u{0020}on\u{0020}the\u{0020}number\u{0020}of\u{0020}<color=#ffbe32>effects</color>\u{0020}on\u{0020}allies\u{0020}or\u{0020}enemies,\u{0020}there\u{0020}is\u{0020}a\u{0020}maximum\u{0020}limit\u{0020}to\u{0020}the\u{0020}number\u{0020}of\u{0020}effects\u{0020}considered,\u{0020}with\u{0020}the\u{0020}highest\u{0020}value\u{0020}being\u{0020}5.", "0", 57, "0", "0", "0", "效果數量", "0"},
[2038] = {2038, 2, "Immunity\u{0020}(Immu.)", 38, "Immunity\u{0020}is\u{0020}divided\u{0020}into\u{0020}<color=#ffbe32>Immunity\u{0020}I</color>\u{0020}and\u{0020}<color=#ffbe32>Immunity\u{0020}II</color>.\n<color=#ffbe32>Immunity\u{0020}I</color>\u{0020}includes\u{0020}immunity\u{0020}to\u{0020}charm,\u{0020}control,\u{0020}debuffs,\u{0020}and\u{0020}immunity\u{0020}to\u{0020}individual\u{0020}continuous\u{0020}effects.\n<color=#ffbe32>Immunity\u{0020}II</color>\u{0020}includes\u{0020}immunity\u{0020}to\u{0020}all\u{0020}debuffs\u{0020}and\u{0020}immunity\u{0020}to\u{0020}all\u{0020}buffs,\u{0020}a\u{0020}broader\u{0020}range\u{0020}of\u{0020}immunities.\u{0020}(Immunity\u{0020}I\u{0020}is\u{0020}included\u{0020}within\u{0020}Immunity\u{0020}II.)", "0", 0, "0", "0", "0", "0", "0"},
[2039] = {2039, 2, "Ignores\u{0020}Basic\u{0020}Immunity/Ignores\u{0020}Total\u{0020}Immunity", 39, "The\u{0020}effects\u{0020}of\u{0020}this\u{0020}Skill\u{0020}bypasses\u{0020}<color=#ffbe32>Basic\u{0020}Immunity</color>/<color=#ffbe32>Total\u{0020}Immunity</color>.", "0", 0, "0", "0", "0", "0", "0"},
[3001] = {3001, 3, "Level\u{0020}(Lv.)", 1, "As\u{0020}the\u{0020}<color=#ffbe32>driver\u{0020}level</color>\u{0020}increases,\u{0020}the\u{0020}driver's\u{0020}basic\u{0020}atats\u{0020}also\u{0020}improve.\u{0020}The\u{0020}<color=#ffbe32>driver\u{0020}level</color>\u{0020}can\u{0020}be\u{0020}increased\u{0020}by\u{0020}engaging\u{0020}in\u{0020}combat\u{0020}that\u{0020}consumes\u{0020}stamina\u{0020}or\u{0020}by\u{0020}using\u{0020}<color=#ffbe32>Data\u{0020}Salvage</color>.", "0", 58, "0", "0", "0", "驾驶员等级", "随着<color=#ffbe32>驾驶员等级</color>提高，驾驶员的各项基础能力也会提高。<color=#ffbe32>驾驶员等级</color>可以通过进行消耗体力的作战或是使用回收资料来提升。"},
[3002] = {3002, 3, "Health\u{0020}(HP)", 2, "Current\u{0020}remaining\u{0020}<color=#ffbe32>HP</color>\u{0020}of\u{0020}an\u{0020}entity.\u{0020}When\u{0020}an\u{0020}entity's\u{0020}HP\u{0020}hits\u{0020}0,\u{0020}the\u{0020}entity\u{0020}is\u{0020}defeated\u{0020}and\u{0020}becomes\u{0020}unable\u{0020}to\u{0020}fight.", "0", 59, "0", "0", "0", "生命值", "单位的<color=#ffbe32>生命值</color>归零就会处于战斗不能状态。"},
[3003] = {3003, 3, "Attack\u{0020}Power\u{0020}(ATK)", 3, "Basic\u{0020}damage\u{0020}value\u{0020}of\u{0020}an\u{0020}entity.\u{0020}Primarily\u{0020}defines\u{0020}how\u{0020}much\u{0020}damage\u{0020}an\u{0020}entity\u{0020}can\u{0020}inflict\u{0020}with\u{0020}its\u{0020}normal\u{0020}attack./nIt\u{0020}is\u{0020}also\u{0020}used\u{0020}as\u{0020}a\u{0020}base\u{0020}value\u{0020}of\u{0020}various\u{0020}damage\u{0020}effects\u{0020}after\u{0020}the\u{0020}entity's\u{0020}normal\u{0020}attack.", "0", 60, "0", "0", "0", "攻击力", "<color=#ffbe32>攻击力</color>会影响驾驶员造成的伤害，攻击力越高造成的伤害越高。"},
[3004] = {3004, 3, "Armor", 4, "Defensive\u{0020}statistics.\u{0020}Reduces\u{0020}damage\u{0020}received\u{0020}by\u{0020}the\u{0020}entity\u{0020}by\u{0020}its\u{0020}armor\u{0020}percentage\u{0020}value./nIgnored\u{0020}by\u{0020}<color=#ffbe32>Fixed\u{0020}Damage</color>\u{0020}and\u{0020}<color=#ffbe32>True\u{0020}Damage</color>\u{0020}type\u{0020}effects.", "0", 61, "0", "0", "0", "装甲值", "<color=#ffbe32>装甲值</color>能够减少驾驶员受到的伤害，如果<color=#ffbe32>装甲值</color>到达百分之百，则伤害就会降低百分之百。这时就需要通过使用<color=#ffbe32>弱化类</color>技能降低目标的装甲值，或是使用<color=#ffbe32>固定伤害</color>和<color=#ffbe32>真实伤害</color>无视装甲值造成伤害。"},
[3005] = {3005, 3, "Critical\u{0020}Chance\u{0020}(Crit.\u{0020}Chance)", 5, "The\u{0020}chances\u{0020}of\u{0020}triggering\u{0020}a\u{0020}critical\u{0020}when\u{0020}an\u{0020}entity\u{0020}attacks.\u{0020}<color=#ffbe32>Fixed\u{0020}Damage</color>\u{0020}cannot\u{0020}crit.", "0", 62, "0", "0", "0", "致命率", "<color=#ffbe32>致命率</color>决定触发致命攻击的几率。"},
[3006] = {3006, 3, "Critical\u{0020}Power\u{0020}(Crit.\u{0020}Power)", 6, "The\u{0020}rate\u{0020}of\u{0020}damage\u{0020}and\u{0020}support\u{0020}effect\u{0020}values\u{0020}would\u{0020}be\u{0020}boosted\u{0020}if\u{0020}landing\u{0020}a\u{0020}critical.", "0", 63, "0", "0", "0", "致命伤害", "<color=#ffbe32>致命伤害</color>决定触发致命攻击时伤害的提升量。"},
[3007] = {3007, 3, "Overcap Crit Damage", 7, "<color=#ffbe32>Overcap Crit Damage</color> determines the increase in damage when a critical hit is triggered. Overcap Crit Damage is not subject to the critical damage cap.  ", "0", 114, "0", "0", "0", "致命伤害", "<color=#ffbe32>致命伤害</color>决定触发致命攻击时伤害的提升量。"},
[3008] = {3008, 3, "Mobility\u{0020}(MOB)", 8, "<color=#ffbe32>Mobility</color>\u{0020}determines\u{0020}the\u{0020}chance\u{0020}to\u{0020}trigger\u{0020}an\u{0020}<color=#ffbe32>Avoidance\u{0020}Critical</color>.\u{0020}The\u{0020}higher\u{0020}the\u{0020}<color=#ffbe32>mobility</color>,\u{0020}the\u{0020}easier\u{0020}it\u{0020}is\u{0020}to\u{0020}trigger\u{0020}an\u{0020}<color=#ffbe32>Avoidance\u{0020}Critical</color>.\nWhen\u{0020}an\u{0020}<color=#ffbe32>Avoidance\u{0020}Critical</color>\u{0020}is\u{0020}triggered,\u{0020}it\u{0020}can\u{0020}reduce\u{0020}the\u{0020}damage\u{0020}of\u{0020}that\u{0020}attack\u{0020}by\u{0020}35%,\u{0020}and\u{0020}the\u{0020}duration\u{0020}of\u{0020}any\u{0020}debuffs\u{0020}caused\u{0020}by\u{0020}the\u{0020}attack\u{0020}will\u{0020}also\u{0020}be\u{0020}halved.", "sdcg_zszd13", 64, "0", "0", "0", "机动力", "<color=#ffbe32>机动力</color>决定触发闪避直击的几率，<color=#ffbe32>机动力</color>越高越容易触发闪避直击。\n触发闪避直击时能够减少该次攻击的百分之35伤害，并且该次攻击造成的减益状态的持续时间也会减半。"},
[3009] = {3009, 3, "Level\u{0020}Up", 9, "<color=#ffbe32>Upgrading</color>\u{0020}can\u{0020}improve\u{0020}the\u{0020}driver's\u{0020}<color=#ffbe32>basic\u{0020}stats</color>.\u{0020}Upgrades\u{0020}can\u{0020}be\u{0020}performed\u{0020}by\u{0020}consuming\u{0020}Report\u{0020}Data\u{0020}and\u{0020}Shield\u{0020}Credits.", "sdcg_jc2", 65, "0", "0", "0", "升级", "<color=#ffbe32>升级</color>能够提高驾驶员的各项基础能力，消耗报告资料和盾币就能进行<color=#ffbe32>升级</color>。"},
[3010] = {3010, 3, "Shield\u{0020}Effectiveness", 10, "<color=#ffbe32>Shield\u{0020}Effectiveness</color>\u{0020}determines\u{0020}the\u{0020}amount\u{0020}of\u{0020}Shield\u{0020}gained\u{0020}when\u{0020}receiving\u{0020}a\u{0020}Shield.", "0", 115, "0", "0", "0", "机动力", "<color=#ffbe32>机动力</color>决定触发闪避直击的几率，<color=#ffbe32>机动力</color>越高越容易触发闪避直击。\n触发闪避直击时能够减少该次攻击的百分之35伤害，并且该次攻击造成的减益状态的持续时间也会减半。"},
[3011] = {3011, 3, "Breakthrough", 11, "When\u{0020}the\u{0020}driver\u{0020}level\u{0020}reaches\u{0020}the\u{0020}current\u{0020}max\u{0020}level,\u{0020}<color=#ffbe32>Breakthrough</color>\u{0020}can\u{0020}be\u{0020}performed\u{0020}by\u{0020}consuming\u{0020}Transformation\u{0020}Star\u{0020}Shards\u{0020}and\u{0020}Shield\u{0020}Credits.\nAfter\u{0020}<color=#ffbe32>Breakthrough</color>,\u{0020}the\u{0020}driver's\u{0020}level\u{0020}cap\u{0020}and\u{0020}ability\u{0020}scaling\u{0020}will\u{0020}be\u{0020}increased.\u{0020}When\u{0020}the\u{0020}star\u{0020}level\u{0020}reaches\u{0020}6\u{0020}stars,\u{0020}<color=#ffbe32>Breakthrough</color>\u{0020}can\u{0020}no\u{0020}longer\u{0020}be\u{0020}performed.", "sdcg_qzjc2", 66, "0", "0", "0", "界限突破", "当驾驶员星级不为6并且等级达到当前的满级时，可以消耗幻化星碎和盾币进行<color=#ffbe32>界限突破</color>。\n<color=#ffbe32>界限突破</color>后驾驶员的等级会回到1级，但是等级上限和能力成长会有所提高。星级达到6星时，无法再进行<color=#ffbe32>界限突破</color>。"},
[3012] = {3012, 3, "Awakening", 12, "After\u{0020}the\u{0020}driver\u{0020}has\u{0020}undergone\u{0020}one\u{0020}<color=#ffbe32>Breakthrough</color>,\u{0020}they\u{0020}can\u{0020}perform\u{0020}<color=#ffbe32>Awakening</color>\u{0020}by\u{0020}consuming\u{0020}the\u{0020}corresponding\u{0020}type\u{0020}of\u{0020}Awakening\u{0020}Crystal\u{0020}and\u{0020}Shield\u{0020}Credits.\u{0020}After\u{0020}<color=#ffbe32>Awakening</color>,\u{0020}the\u{0020}driver\u{0020}will\u{0020}improve\u{0020}various\u{0020}basic\u{0020}stats\u{0020}and\u{0020}unlock\u{0020}<color=#ffbe32>Awakening\u{0020}Skills</color>.", "0", 67, "0", "0", "0", "觉醒", "驾驶员进行过一次界限突破后就能够消耗对应种类的觉醒水晶和盾币进行<color=#ffbe32>觉醒</color>。<color=#ffbe32>觉醒</color>后驾驶员会提高各项基本能力，并且会解锁<color=#ffbe32>觉醒技能</color>。"},
[3013] = {3013, 3, "Skill\u{0020}Upgrade", 13, "By\u{0020}using\u{0020}Shield\u{0020}Credits\u{0020}and\u{0020}the\u{0020}driver's\u{0020}exclusive\u{0020}[Reverb]\u{0020}item,\u{0020}you\u{0020}can\u{0020}enhance\u{0020}the\u{0020}driver's\u{0020}skill\u{0020}levels.\u{0020}The\u{0020}skill\u{0020}level\u{0020}that\u{0020}can\u{0020}be\u{0020}enhanced\u{0020}through\u{0020}<color=#ffbe32>Skill\u{0020}Upgrade</color>\u{0020}is\u{0020}up\u{0020}to\u{0020}level\u{0020}9\u{0020}(when\u{0020}the\u{0020}driver\u{0020}has\u{0020}collected\u{0020}all\u{0020}3\u{0020}pieces\u{0020}of\u{0020}Resonance\u{0020}Gear,\u{0020}the\u{0020}skill\u{0020}level\u{0020}increases\u{0020}by\u{0020}1.\u{0020}The\u{0020}maximum\u{0020}skill\u{0020}level\u{0020}is\u{0020}10).", "sdcg_qzjc1", 68, "0", "0", "0", "技能强化", "通过使用盾币和驾驶员入队时的星级对应的极巅计划书（5星）/战略简述（4星）/特训单表（3星）就能提升驾驶员的技能等级，可通过<color=#ffbe32>技能强化</color>提升的技能等级最高为9级（当驾驶员自身3件共鸣装备均为满级时，技能等级会提高1级。技能等级最高为10级）。"},
[3014] = {3014, 3, "Gear\u{0020}Core\u{0020}Module", 14, "<color=#ffbe32>Gear\u{0020}Core\u{0020}Modules</color>\u{0020}can\u{0020}enhance\u{0020}various\u{0020}different\u{0020}attributes.\u{0020}The\u{0020}higher\u{0020}the\u{0020}level,\u{0020}Star\u{0020}Rank,\u{0020}and\u{0020}quality,\u{0020}the\u{0020}greater\u{0020}the\u{0020}corresponding\u{0020}ability\u{0020}scores\u{0020}are\u{0020}improved.", "0", 69, "0", "0", "0", "机甲核心", "<color=#ffbe32>机甲核心</color>可以提升各项不同的能力值。等级、星级、品质越高，提升的对应能力值越高。此外，5星史诗+以上品质的<color=#ffbe32>机甲核心</color>还会附带各种不同的核心技能。"},
[3015] = {3015, 3, "Core\u{0020}Upgrade", 15, "Consuming\u{0020}Shield\u{0020}Credits\u{0020}and\u{0020}other\u{0020}Gear\u{0020}Core\u{0020}Modules\u{0020}can\u{0020}be\u{0020}used\u{0020}for\u{0020}<color=#ffbe32>Upgrading</color>,\u{0020}which\u{0020}increases\u{0020}the\u{0020}level\u{0020}of\u{0020}the\u{0020}Gear\u{0020}Core\u{0020}Module.\u{0020}During\u{0020}the\u{0020}upgrade\u{0020}process,\u{0020}ability\u{0020}scores\u{0020}will\u{0020}be\u{0020}randomly\u{0020}improved\u{0020}within\u{0020}a\u{0020}certain\u{0020}range\u{0020}(if\u{0020}the\u{0020}improvement\u{0020}is\u{0020}not\u{0020}the\u{0020}maximum,\u{0020}it\u{0020}can\u{0020}be\u{0020}further\u{0020}enhanced\u{0020}through\u{0020}development).\nGear\u{0020}Core\u{0020}Modules\u{0020}of\u{0020}5\u{0020}stars\u{0020}and\u{0020}above\u{0020}can\u{0020}be\u{0020}<color=#ffbe32>Upgraded</color>\u{0020}to\u{0020}a\u{0020}higher\u{0020}quality\u{0020}Gear\u{0020}Core\u{0020}Module\u{0020}when\u{0020}they\u{0020}reach\u{0020}the\u{0020}maximum\u{0020}level,\u{0020}at\u{0020}which\u{0020}point\u{0020}the\u{0020}level\u{0020}of\u{0020}the\u{0020}Gear\u{0020}Core\u{0020}Module\u{0020}will\u{0020}revert\u{0020}to\u{0020}level\u{0020}5,\u{0020}and\u{0020}the\u{0020}ability\u{0020}growth\u{0020}will\u{0020}be\u{0020}increased.\nWhen\u{0020}the\u{0020}quality\u{0020}reaches\u{0020}5-star\u{0020}S\u{0020}and\u{0020}the\u{0020}module\u{0020}is\u{0020}at\u{0020}maximum\u{0020}level,\u{0020}a\u{0020}subsequent\u{0020}<color=#ffbe32>Upgrading</color>\u{0020}will\u{0020}transform\u{0020}it\u{0020}into\u{0020}a\u{0020}6-star\u{0020}Gear\u{0020}Core\u{0020}Module.", "0", 70, "0", "0", "0", "机甲核心强化", "消耗盾币及其他的机甲核心可以进行<color=#ffbe32>强化</color>，提升机甲核心的等级。升级时会在一定范围内随机提升能力值（若提升的不是最大值，则可以通过开发提升其能力值。）。\n5星及以上的机甲核心在等级达到满级时还可以将其<color=#ffbe32>进阶</color>成高一级品质的机甲核心，此时机甲核心等级会回到0级，能力成长会提升。\n品质达到5星传说+满级时，再次<color=#ffbe32>进阶</color>就会变为6星精良级机甲核心。"},
[3016] = {3016, 3, "Core\u{0020}Augmentation", 16, "Performing\u{0020}<color=#ffbe32>Augment</color>\u{0020}can\u{0020}increase\u{0020}the\u{0020}<color=#ffbe32>Augmentation</color>\u{0020}level\u{0020}of\u{0020}the\u{0020}Gear\u{0020}Core\u{0020}Module.\nThe\u{0020}higher\u{0020}the\u{0020}<color=#ffbe32>Augmentation</color>\u{0020}level,\u{0020}the\u{0020}greater\u{0020}the\u{0020}stats\u{0020}improvements\u{0020}the\u{0020}Gear\u{0020}Core\u{0020}Module\u{0020}provides,\u{0020}with\u{0020}the\u{0020}maximum\u{0020}being\u{0020}one\u{0020}hundred\u{0020}percent\u{0020}(reaching\u{0020}one\u{0020}hundred\u{0020}percent\u{0020}means\u{0020}the\u{0020}Gear\u{0020}Core\u{0020}Module\u{0020}will\u{0020}always\u{0020}randomly\u{0020}yield\u{0020}the\u{0020}maximum\u{0020}values\u{0020}during\u{0020}upgrades).", "0", 71, "0", "0", "0", "机甲核心开发", "进行<color=#ffbe32>开发</color>可以提高机甲核心的<color=#ffbe32>开发度</color>。\n<color=#ffbe32>开发度</color>越高机甲核心带来的能力值提升越高，最高为百分之一百（百分之一百时的数值即为强化升级时每次都随机出最大值的状态）。"},
[3017] = {3017, 3, "Resonance\u{0020}Gear", 17, "Consuming\u{0020}<color=#ffbe32>Raw\u{0020}Resonant\u{0020}Crystals</color>\u{0020}allows\u{0020}you\u{0020}to\u{0020}obtain\u{0020}<color=#ffbe32>Resonance\u{0020}Gear</color>\u{0020}in\u{0020}the\u{0020}supply\u{0020}interface.\u{0020}Duplicate\u{0020}<color=#ffbe32>Resonance\u{0020}Gear</color>\u{0020}will\u{0020}automatically\u{0020}transform\u{0020}into\u{0020}<color=#ffbe32>Resonant\u{0020}Crystalline</color>.\nConsuming\u{0020}<color=#ffbe32>Resonant\u{0020}Crystalline</color>\u{0020}and\u{0020}Shield\u{0020}Credits\u{0020}can\u{0020}be\u{0020}used\u{0020}to\u{0020}enhance\u{0020}the\u{0020}Resonance\u{0020}Gear.\u{0020}When\u{0020}a\u{0020}driver\u{0020}has\u{0020}collected\u{0020}all\u{0020}three\u{0020}pieces\u{0020}of\u{0020}<color=#ffbe32>Resonance\u{0020}Gear</color>,\u{0020}the\u{0020}driver's\u{0020}<color=#ffbe32>skill\u{0020}level</color>\u{0020}will\u{0020}increase\u{0020}by\u{0020}one.", "sdcg_qzjc3", 72, "0", "0", "0", "共鸣装备", "消耗<color=#ffbe32>共鸣原石</color>可以在补给界面中入手<color=#ffbe32>共鸣装备</color>。重复的<color=#ffbe32>共鸣装备</color>会自动变化为<color=#ffbe32>共鸣结晶体</color>。\n消耗<color=#ffbe32>共鸣结晶体</color>和盾币就可以强化共鸣装备。当驾驶员自身三件<color=#ffbe32>共鸣装备</color>全都满级时，该驾驶员的<color=#ffbe32>技能等级</color>就会提高一级。"},
[3018] = {3018, 3, "Overlimit\u{0020}Resonance\u{0020}Gear", 18, "Consuming\u{0020}<color=#ffbe32>Breakthrough\u{0020}Resonance\u{0020}Factors</color>\u{0020}and\u{0020}<color=#ffbe32>Nimbus\u{0020}Crystals</color>\u{0020}from\u{0020}powerful\u{0020}sins\u{0020}can\u{0020}unlock\u{0020}the\u{0020}driver's\u{0020}<color=#ffbe32>Overlimit\u{0020}Resonance\u{0020}Gear</color>\u{0020}and\u{0020}grant\u{0020}a\u{0020}one-time\u{0020}skill\u{0020}enhancement\u{0020}effect.\nConsuming\u{0020}<color=#ffbe32>Resonant\u{0020}Crystalline</color>\u{0020}and\u{0020}Shield\u{0020}Credits\u{0020}can\u{0020}be\u{0020}used\u{0020}to\u{0020}enhance\u{0020}the\u{0020}Overlimit\u{0020}Resonance\u{0020}Gear.\u{0020}When\u{0020}the\u{0020}driver's\u{0020}<color=#ffbe32>Overlimit\u{0020}Resonance\u{0020}Gear</color>\u{0020}reaches\u{0020}level\u{0020}30,\u{0020}the\u{0020}driver\u{0020}will\u{0020}receive\u{0020}an\u{0020}additional\u{0020}skill\u{0020}enhancement\u{0020}effect.", "0", 113, "0", "0", "0", "0", "0"},
[4001] = {4001, 4, "Mailbox", 1, "In\u{0020}the\u{0020}<color=#ffbe32>Mailbox</color>,\u{0020}you\u{0020}can\u{0020}claim\u{0020}system\u{0020}mails\u{0020}and\u{0020}rewards,\u{0020}and\u{0020}also\u{0020}archive\u{0020}birthday\u{0020}greeting\u{0020}mails\u{0020}in\u{0020}the\u{0020}memoirs.", "0", 73, "0", "0", "0", "邮箱", "<color=#ffbe32>邮箱</color>界面中可以领取系统发送的邮件和奖励。"},
[4002] = {4002, 4, "Settings", 2, "In\u{0020}the\u{0020}<color=#ffbe32>Settings</color>,\u{0020}you\u{0020}can\u{0020}adjust\u{0020}various\u{0020}configurations\u{0020}such\u{0020}as\u{0020}in-game\u{0020}sound\u{0020}and\u{0020}text.", "0", 74, "0", "0", "0", "设置", "<color=#ffbe32>设置</color>界面中可以调整游戏内声音、文本等各项配置。"},
[4003] = {4003, 4, "Inventory", 3, "In\u{0020}the\u{0020}<color=#ffbe32>Inventory</color>,\u{0020}you\u{0020}can\u{0020}view\u{0020}the\u{0020}items,\u{0020}Gear\u{0020}Core\u{0020}Modules,\u{0020}and\u{0020}Resonance\u{0020}Gear.", "0", 75, "0", "0", "0", "背包", "<color=#ffbe32>背包</color>界面中可以查看持有的道具、机甲核心及共鸣装备。"},
[4004] = {4004, 4, "Tasks", 4, "In\u{0020}the\u{0020}<color=#ffbe32>Task</color>,\u{0020}you\u{0020}can\u{0020}check\u{0020}the\u{0020}completion\u{0020}status\u{0020}of\u{0020}various\u{0020}tasks\u{0020}and\u{0020}your\u{0020}<color=#ffbe32>Activity\u{0020}Score</color>.\nTasks\u{0020}are\u{0020}categorized\u{0020}by\u{0020}refresh\u{0020}time\u{0020}into\u{0020}daily,\u{0020}weekly,\u{0020}and\u{0020}monthly\u{0020}types,\u{0020}each\u{0020}with\u{0020}their\u{0020}own\u{0020}<color=#ffbe32>Activity\u{0020}Score</color>.\u{0020}After\u{0020}completing\u{0020}tasks\u{0020}or\u{0020}reaching\u{0020}the\u{0020}specified\u{0020}amount\u{0020}of\u{0020}<color=#ffbe32>Activity\u{0020}Score</color>,\u{0020}you\u{0020}can\u{0020}claim\u{0020}the\u{0020}corresponding\u{0020}rewards.", "0", 76, "0", "0", "0", "任务", "<color=#ffbe32>任务</color>界面中可以查看各项任务的完成情况及<color=#ffbe32>活跃积分</color>。\n任务根据刷新时间分为日、周、月三种类型，每种类型都有各自的<color=#ffbe32>活跃积分</color>。完成任务或<color=#ffbe32>活跃积分</color>达到指定数值后就能领取对应的奖励。"},
[4005] = {4005, 4, "Database", 5, "In\u{0020}the\u{0020}<color=#ffbe32>Database</color>,\u{0020}you\u{0020}can\u{0020}view\u{0020}the\u{0020}character,\u{0020}Sin,\u{0020}badge,\u{0020}art,\u{0020}skill,\u{0020}and\u{0020}achievement\u{0020}database.", "0", 78, "0", "0", "0", "图鉴", "<color=#ffbe32>图鉴</color>界面中可以包含角色阵营、技能图鉴、原罪图鉴、勋章图鉴、美术馆、剧情回放及帮助界面。"},
[4006] = {4006, 4, "Achievements\u{0020}System", 6, "In\u{0020}the\u{0020}<color=#ffbe32>Achievements</color>,\u{0020}you\u{0020}can\u{0020}check\u{0020}the\u{0020}progress\u{0020}of\u{0020}various\u{0020}achievements.\u{0020}Completing\u{0020}achievements\u{0020}earns\u{0020}you\u{0020}corresponding\u{0020}rewards\u{0020}and\u{0020}badge.", "0", 77, "0", "0", "0", "成就", "<color=#ffbe32>成就</color>界面中可以查看各项成就的完成进度。完成成就可以获得对应的奖励及勋章。"},
[4007] = {4007, 4, "Drivers\u{0020}Database", 7, "In\u{0020}the\u{0020}<color=#ffbe32>Character\u{0020}Factions</color>,\u{0020}you\u{0020}can\u{0020}view\u{0020}the\u{0020}teams\u{0020}that\u{0020}each\u{0020}driver\u{0020}belongs\u{0020}to\u{0020}and\u{0020}their\u{0020}detailed\u{0020}information.", "0", 79, "0", "0", "0", "角色阵营", "<color=#ffbe32>角色阵营</color>中可以查看各个驾驶员所属的队伍及详细信息。"},
[4008] = {4008, 4, "Sins\u{0020}Database", 8, "In\u{0020}the\u{0020}<color=#ffbe32>Sins\u{0020}Database</color>,\u{0020}you\u{0020}can\u{0020}view\u{0020}information\u{0020}about\u{0020}enemy\u{0020}units\u{0020}that\u{0020}appear\u{0020}in\u{0020}the\u{0020}game.", "0", 80, "0", "0", "0", "原罪图鉴", "<color=#ffbe32>原罪图鉴</color>中可以查看游戏中出现的敌方单位的情报。"},
[4009] = {4009, 4, "Badge\u{0020}Database", 9, "In\u{0020}the\u{0020}<color=#ffbe32>Badge\u{0020}Database</color>,\u{0020}you\u{0020}can\u{0020}view\u{0020}the\u{0020}acquisition\u{0020}status\u{0020}and\u{0020}conditions\u{0020}for\u{0020}each\u{0020}badge.", "0", 81, "0", "0", "0", "勋章图鉴", "<color=#ffbe32>勋章图鉴</color>中可以查看各个勋章的获取情况及获取条件。"},
[4010] = {4010, 4, "Gallary", 10, "In\u{0020}the\u{0020}<color=#ffbe32>Gallery</color>,\u{0020}you\u{0020}can\u{0020}view\u{0020}illustrations,\u{0020}animations,\u{0020}and\u{0020}musics\u{0020}in\u{0020}the\u{0020}game.", "0", 82, "0", "0", "0", "美术馆", "<color=#ffbe32>美术馆</color>中可以查看游戏中出现的插画、动画及音乐。"},
[4011] = {4011, 4, "Skill\u{0020}Database", 11, "In\u{0020}the\u{0020}<color=#ffbe32>Skill\u{0020}Database</color>,\u{0020}you\u{0020}can\u{0020}view\u{0020}skill\u{0020}effects\u{0020}by\u{0020}category\u{0020}and\u{0020}the\u{0020}drivers\u{0020}who\u{0020}possess\u{0020}these\u{0020}skills.", "0", 83, "0", "0", "0", "剧情回放", "<color=#ffbe32>剧情回放</color>中可以查看已经通过的剧情。"},
[4012] = {4012, 4, "Shop", 12, "In\u{0020}the\u{0020}<color=#ffbe32>Shop</color>,\u{0020}you\u{0020}can\u{0020}purchase\u{0020}various\u{0020}resources.\u{0020}You\u{0020}can\u{0020}also\u{0020}exchange\u{0020}different\u{0020}items\u{0020}using\u{0020}the\u{0020}<color=#ffbe32>Exchange\u{0020}Materials</color>\u{0020}you\u{0020}have\u{0020}obtained.", "0", 84, "0", "0", "0", "商城", "<color=#ffbe32>商城</color>中可以购买各项资源。同时也可以使用获得的<color=#ffbe32>交换材料</color>兑换不同道具。"},
[4013] = {4013, 4, "Driver", 13, "In\u{0020}the\u{0020}<color=#ffbe32>Drivers</color>,\u{0020}you\u{0020}can\u{0020}view\u{0020}the\u{0020}drivers\u{0020}you\u{0020}have.", "0", 85, "0", "0", "0", "驾驶员", "<color=#ffbe32>驾驶员</color>界面可以查看自己已经获得的驾驶员并对她们进行养成。"},
[4014] = {4014, 4, "Requisition\u{0020}", 14, "In\u{0020}the\u{0020}<color=#ffbe32>Requisition</color>,\u{0020}you\u{0020}can\u{0020}recruit\u{0020}new\u{0020}drivers\u{0020}into\u{0020}your\u{0020}team\u{0020}by\u{0020}consuming\u{0020}<color=#ffbe32>Requisition\u{0020}tickets</color>\u{0020}or\u{0020}<color=#ffbe32>Prime\u{0020}Crystalline</color>,\u{0020}and\u{0020}also\u{0020}obtain\u{0020}resonance\u{0020}gear\u{0020}by\u{0020}consuming\u{0020}<color=#ffbe32>Raw\u{0020}Resonant\u{0020}Crystals</color>.", "0", 86, "0", "0", "0", "补给", "<color=#ffbe32>补给</color>界面中可以通过消耗调度券或原初结晶征调新的驾驶员入队，也可以消耗共鸣原石获取共鸣装备。"},
[4015] = {4015, 4, "Drill", 15, "<color=#ffbe32>Drill</color>\u{0020}are\u{0020}combats\u{0020}between\u{0020}drivers.\nEach\u{0020}week\u{0020}marks\u{0020}a\u{0020}new\u{0020}season,\u{0020}and\u{0020}at\u{0020}the\u{0020}end\u{0020}of\u{0020}the\u{0020}current\u{0020}season,\u{0020}you\u{0020}will\u{0020}receive\u{0020}corresponding\u{0020}rewards\u{0020}based\u{0020}on\u{0020}your\u{0020}ranking.\u{0020}The\u{0020}number\u{0020}of\u{0020}challenges\u{0020}will\u{0020}recover\u{0020}over\u{0020}time,\u{0020}and\u{0020}when\u{0020}you\u{0020}have\u{0020}no\u{0020}challenges\u{0020}left,\u{0020}you\u{0020}can\u{0020}participate\u{0020}using\u{0020}an\u{0020}Elite\u{0020}Drill\u{0020}Ticket.\u{0020}In\u{0020}addition,\u{0020}the\u{0020}<color=#ffbe32>Elite\u{0020}Drill\u{0020}Token</color>\u{0020}earned\u{0020}from\u{0020}participating\u{0020}can\u{0020}be\u{0020}exchanged\u{0020}for\u{0020}various\u{0020}items\u{0020}in\u{0020}the\u{0020}shop.", "0", 87, "0", "0", "0", "精英演习", "<color=#ffbe32>精英演习</color>可以让所有驾驶员参加。\n每周为一个新赛季，根据当前赛季中的排名每周结束后会获得对应的奖励。\n可挑战次数会随着时间恢复，无挑战次数时可以使用精英演习入场券参加。此外，参加获得的<color=#ffbe32>精英纪念币</color>可以在商城兑换各种道具。"},
[4016] = {4016, 4, "Battle", 16, "In\u{0020}the\u{0020}<color=#ffbe32>Battle</color>,\u{0020}you\u{0020}can\u{0020}engage\u{0020}in\u{0020}various\u{0020}types\u{0020}of\u{0020}operations,\u{0020}including\u{0020}<color=#ffbe32>Main\u{0020}Story</color>,\u{0020}<color=#ffbe32>Resource</color>,\u{0020}<color=#ffbe32>Tactical\u{0020}Tutorial</color>,\u{0020}<color=#ffbe32>Red\u{0020}Tower</color>,\u{0020}<color=#ffbe32>Joint\u{0020}Crusade</color>,\u{0020}and\u{0020}<color=#ffbe32>Event</color>.", "0", 88, "0", "0", "0", "作战", "<color=#ffbe32>作战</color>界面中可以进行各项不同的作战。包含主线关卡、资源关卡、战术指导、红色巨塔、联合讨伐及活动作战。"},
[4017] = {4017, 4, "Main\u{0020}Story", 17, "In\u{0020}the\u{0020}<color=#ffbe32>Main\u{0020}Story</color>,\u{0020}you\u{0020}can\u{0020}experience\u{0020}the\u{0020}storyline\u{0020}by\u{0020}playing\u{0020}through\u{0020}the\u{0020}main\u{0020}story\u{0020}levels.\nEach\u{0020}level's\u{0020}completion\u{0020}is\u{0020}rated\u{0020}from\u{0020}0\u{0020}to\u{0020}3\u{0020}stars,\u{0020}with\u{0020}3\u{0020}stars\u{0020}providing\u{0020}additional\u{0020}rewards.\u{0020}Additionally,\u{0020}you\u{0020}can\u{0020}receive\u{0020}extra\u{0020}rewards\u{0020}based\u{0020}on\u{0020}the\u{0020}overall\u{0020}star\u{0020}rating\u{0020}achieved\u{0020}for\u{0020}each\u{0020}chapter.", "0", 89, "0", "0", "0", "主线", "<color=#ffbe32>主线</color>中可以体验剧情游玩主线关卡。\n根据完成情况每关的评价都分为0星到3星，以3星通过会有额外的奖励。根据章节整体的星数获得度也能获得额外的奖励。"},
[4018] = {4018, 4, "Shield\u{0020}Credits\u{0020}Recycling", 18, "In\u{0020}the\u{0020}Shield\u{0020}Credits\u{0020}Recycling\u{0020}battle,\u{0020}you\u{0020}can\u{0020}obtain\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}shield\u{0020}credits\u{0020}that\u{0020}can\u{0020}be\u{0020}used\u{0020}in\u{0020}various\u{0020}places.", "0", 90, "0", "0", "0", "盾币回收", "<color=#ffbe32>盾币收集</color>作战中可以大量获得能够使用在各种地方的盾币。"},
[4019] = {4019, 4, "Purge\u{0020}of\u{0020}Sins", 19, "In\u{0020}the\u{0020}<color=#ffbe32>Purge\u{0020}of\u{0020}Sins</color>\u{0020}operation,\u{0020}you\u{0020}can\u{0020}obtain\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}report\u{0020}data\u{0020}used\u{0020}to\u{0020}enhance\u{0020}driver\u{0020}levels.", "0", 91, "0", "0", "0", "原罪清剿", "<color=#ffbe32>资料回收</color>作战中能够大量获得用以提升驾驶员等级的报告资料。"},
[4020] = {4020, 4, "Transformation\u{0020}Star\u{0020}Shards", 20, "<color=#ffbe32>Transformation\u{0020}Star\u{0020}Shards</color>\u{0020}operation\u{0020}can\u{0020}obtain\u{0020}a\u{0020}large\u{0020}number\u{0020}of\u{0020}Transformation\u{0020}Star\u{0020}Shards\u{0020}for\u{0020}drivers'\u{0020}breakthrough.", "0", 94, "0", "0", "0", "0", "0"},
[4021] = {4021, 4, "Core\u{0020}Parts", 21, "In\u{0020}the\u{0020}<color=#ffbe32>Core\u{0020}Parts</color>,\u{0020}you\u{0020}can\u{0020}obtain\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}<color=#ffbe32>Gear\u{0020}Core\u{0020}Parts</color>\u{0020}used\u{0020}to\u{0020}generate\u{0020}<color=#ffbe32>Gear\u{0020}Core\u{0020}Modules</color>.\u{0020}The\u{0020}types\u{0020}of\u{0020}<color=#ffbe32>Gear\u{0020}Core\u{0020}Parts</color>\u{0020}that\u{0020}can\u{0020}be\u{0020}obtained\u{0020}from\u{0020}the\u{0020}battle\u{0020}vary\u{0020}daily.", "0", 92, "0", "0", "0", "核心制造", "<color=#ffbe32>核心制造</color>副本中可以大量获得用以生成机甲核心的<color=#ffbe32>核心碎片</color>，作战能够获得的<color=#ffbe32>核心碎片</color>的种类每天都有所不同。"},
[4022] = {4022, 4, "Driver\u{0020}Special\u{0020}Training", 22, "In\u{0020}the\u{0020}<color=#ffbe32>Driver\u{0020}Special\u{0020}Training</color>,\u{0020}you\u{0020}can\u{0020}obtain\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}crystals\u{0020}used\u{0020}for\u{0020}driver\u{0020}awakening.\u{0020}The\u{0020}types\u{0020}of\u{0020}<color=#ffbe32>Awakening\u{0020}Crystals</color>\u{0020}that\u{0020}can\u{0020}be\u{0020}obtained\u{0020}vary\u{0020}daily.", "0", 93, "0", "0", "0", "队员特训", "<color=#ffbe32>队员特训</color>副本中可以获得驾驶员用于界限突破的<color=#ffbe32>幻化星碎</color>及用以觉醒的水晶，每天能够获得的<color=#ffbe32>觉醒水晶</color>的种类有所不同。"},
[4023] = {4023, 4, "Tactical\u{0020}Tutorial", 23, "In\u{0020}the\u{0020}<color=#ffbe32>Tactical\u{0020}Tutorial</color>,\u{0020}you\u{0020}can\u{0020}learn\u{0020}various\u{0020}basic\u{0020}tactics\u{0020}for\u{0020}combat.\u{0020}Rewards\u{0020}are\u{0020}given\u{0020}upon\u{0020}the\u{0020}first\u{0020}completion\u{0020}of\u{0020}each\u{0020}tutorial,\u{0020}and\u{0020}although\u{0020}tutorials\u{0020}can\u{0020}be\u{0020}reviewed,\u{0020}rewards\u{0020}can\u{0020}only\u{0020}be\u{0020}obtained\u{0020}once.", "0", 95, "0", "0", "0", "战术指导", "<color=#ffbe32>战术指导</color>中可以学习各种作战的基本战术，每项指导首次完成时都能获得奖励，指导都可以重复观看，但奖励只能获取一次。"},
[4024] = {4024, 4, "Red\u{0020}Tower", 24, "In\u{0020}the\u{0020}<color=#ffbe32>Red\u{0020}Tower</color>,\u{0020}each\u{0020}level\u{0020}presents\u{0020}numerous\u{0020}challenges.\u{0020}There\u{0020}is\u{0020}no\u{0020}stamina\u{0020}required\u{0020}to\u{0020}attempt\u{0020}challenges,\u{0020}and\u{0020}completing\u{0020}a\u{0020}level\u{0020}unlocks\u{0020}the\u{0020}next\u{0020}one.\u{0020}Rewards\u{0020}are\u{0020}given\u{0020}for\u{0020}the\u{0020}first\u{0020}completion\u{0020}of\u{0020}each\u{0020}challenge.\u{0020}As\u{0020}you\u{0020}progress\u{0020}to\u{0020}higher\u{0020}levels,\u{0020}the\u{0020}difficulty\u{0020}of\u{0020}the\u{0020}levels\u{0020}increases.", "0", 96, "0", "0", "0", "红色巨塔", "<color=#ffbe32>红色巨塔</color>中的关卡设置了诸多挑战，尝试挑战不需要消耗体力，完成一层的关卡后就会解锁下一层的关卡。关卡设置的每项挑战首次达成时都会获得奖励。随着楼层的提高，关卡难度也会提高。"},
[4025] = {4025, 4, "United\u{0020}Crusade", 25, "<color=#ffbe32>Joint\u{0020}Crusade</color>\u{0020}is\u{0020}the\u{0020}battle\u{0020}against\u{0020}powerful\u{0020}Sins.\u{0020}During\u{0020}the\u{0020}Joint\u{0020}Crusade,\u{0020}players\u{0020}can\u{0020}make\u{0020}up\u{0020}to\u{0020}three\u{0020}attacks\u{0020}per\u{0020}day.\u{0020}Each\u{0020}attack\u{0020}earns\u{0020}points\u{0020}that\u{0020}are\u{0020}composed\u{0020}of\u{0020}kill\u{0020}points,\u{0020}turn\u{0020}points,\u{0020}and\u{0020}damage\u{0020}points.\u{0020}When\u{0020}the\u{0020}Joint\u{0020}Crusade\u{0020}ends,\u{0020}players\u{0020}are\u{0020}ranked\u{0020}based\u{0020}on\u{0020}their\u{0020}highest\u{0020}single-day\u{0020}total\u{0020}points,\u{0020}and\u{0020}rewards\u{0020}are\u{0020}distributed\u{0020}accordingly.", "0", 97, "0", "0", "0", "联合讨伐", "<color=#ffbe32>联合讨伐</color>是与其他领航共同讨伐强力原罪的作战。每日可出击的次数为两次，根据两次出击造成的伤害量会得到不同的奖励。在两次出击中达成特定条件还会获得额外的奖励。"},
[4026] = {4026, 4, "Profile", 26, "In\u{0020}the\u{0020}<color=#ffbe32>Profile</color>,\u{0020}you\u{0020}can\u{0020}edit\u{0020}your\u{0020}nickname,\u{0020}greeting\u{0020}message,\u{0020}display\u{0020}badges,\u{0020}and\u{0020}set\u{0020}up\u{0020}an\u{0020}adjutant\u{0020}and\u{0020}support\u{0020}drivers\u{0020}who\u{0020}can\u{0020}provide\u{0020}assistance\u{0020}to\u{0020}other\u{0020}navigators.", "0", 98, "0", "0", "0", "个人信息", "<color=#ffbe32>个人信息</color>界面可以修改昵称、问候语、展示纪念勋章及设定副官与能够给其他领航提供支援的支援驾驶员。"},
[4027] = {4027, 4, "Friends", 27, "In\u{0020}the\u{0020}<color=#ffbe32>Friends</color>,\u{0020}you\u{0020}can\u{0020}add\u{0020}other\u{0020}players\u{0020}as\u{0020}friends\u{0020}and\u{0020}support\u{0020}characters,\u{0020}as\u{0020}well\u{0020}as\u{0020}claim\u{0020}friend\u{0020}tokens.", "0", 99, "0", "0", "0", "好友", "<color=#ffbe32>好友</color>界面可以添加其他玩家为好友，并且可以支援角色、领取好友币。"},
[4028] = {4028, 4, "Command\u{0020}Chamber", 28, "In\u{0020}the\u{0020}<color=#ffbe32>Commander's\u{0020}Office</color>,\u{0020}you\u{0020}can\u{0020}collect\u{0020}resources\u{0020}and\u{0020}dispatch\u{0020}squads\u{0020}for\u{0020}Expedition\u{0020}to\u{0020}explore\u{0020}and\u{0020}acquire\u{0020}resources.", "0", 100, "0", "0", "0", "指挥室", "<color=#ffbe32>指挥室</color>界面可以采集物资，派遣小队远征探索资源。"},
[4029] = {4029, 4, "Event", 29, "Completing\u{0020}<color=#ffbe32>Event</color>\u{0020}levels\u{0020}and\u{0020}<color=#ffbe32>Event</color>\u{0020}tasks\u{0020}can\u{0020}earn\u{0020}you\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}event\u{0020}token,\u{0020}which\u{0020}can\u{0020}be\u{0020}used\u{0020}to\u{0020}purchase\u{0020}items\u{0020}from\u{0020}the\u{0020}event\u{0020}shop.", "0", 101, "0", "0", "0", "活动", "<color=#ffbe32>活动</color>完成活动关卡和活动任务可获取大量活动货币，消耗活动货币从活动商城购买商品。"},
[4030] = {4030, 4, "Maintenance\u{0020}Pool", 30, "The\u{0020}<color=#ffbe32>Maintenance\u{0020}Pool</color>\u{0020}is\u{0020}a\u{0020}place\u{0020}to\u{0020}help\u{0020}drivers\u{0020}relieve\u{0020}physical\u{0020}and\u{0020}mental\u{0020}fatigue.\u{0020}After\u{0020}completing\u{0020}mini-games,\u{0020}you\u{0020}might\u{0020}deepen\u{0020}the\u{0020}bond\u{0020}with\u{0020}the\u{0020}drivers.", "0", 102, "0", "0", "0", "维护池", "<color=#ffbe32>维护池</color>是帮助驾驶员消解身心疲劳的地方。\n顺利完成小游戏后，说不定可以加深与驾驶员的羁绊。"},
[4031] = {4031, 4, "Processing\u{0020}Plant", 31, "The\u{0020}<color=#ffbe32>Processing\u{0020}Plant</color>\u{0020}is\u{0020}a\u{0020}place\u{0020}for\u{0020}producing\u{0020}advanced\u{0020}materials.\u{0020}It\u{0020}requires\u{0020}the\u{0020}consumption\u{0020}of\u{0020}<color=#ffbe32>Shield\u{0020}Credits</color>\u{0020}and\u{0020}corresponding\u{0020}low-level\u{0020}materials.", "0", 103, "0", "0", "0", "维护池", "<color=#ffbe32>维护池</color>是帮助驾驶员消解身心疲劳的地方。\n顺利完成小游戏后，说不定可以加深与驾驶员的羁绊。"},
[4032] = {4032, 4, "Armor\u{0020}Enhancement", 32, "In\u{0020}the\u{0020}<color=#ffbe32>Armor\u{0020}Enhancement\u{0020}Operation</color>,\u{0020}defeating\u{0020}powerful\u{0020}sins\u{0020}previously\u{0020}encountered\u{0020}earns\u{0020}Nimbus\u{0020}Fragments\u{0020}used\u{0020}to\u{0020}unlock\u{0020}Overlimit\u{0020}Resonance\u{0020}Gear.\u{0020}These\u{0020}can\u{0020}later\u{0020}be\u{0020}synthesized\u{0020}into\u{0020}Nimbus\u{0020}Crystals\u{0020}in\u{0020}the\u{0020}Processing\u{0020}Plant\u{0020}at\u{0020}the\u{0020}Commander's\u{0020}Office.", "0", 112, "0", "0", "0", "0", "0"},
[5001] = {5001, 5, "Player\u{0020}Level", 1, "As\u{0020}the\u{0020}<color=#ffbe32>Player\u{0020}Level</color>\u{0020}increases,\u{0020}the\u{0020}maximum\u{0020}stamina\u{0020}will\u{0020}be\u{0020}enhanced.", "0", 104, "0", "0", "0", "领航等级", "随着<color=#ffbe32>领航等级</color>的提升，体力值上限会有所提升。此外，各项系统功能也会根据<color=#ffbe32>领航等级</color>来解锁。"},
[5002] = {5002, 5, "Stamina", 2, "Most\u{0020}battles\u{0020}consume\u{0020}<color=#ffbe32>Stamina</color>,\u{0020}and\u{0020}upon\u{0020}completion,\u{0020}the\u{0020}navigator\u{0020}will\u{0020}receive\u{0020}a\u{0020}certain\u{0020}amount\u{0020}of\u{0020}EXP\u{0020}based\u{0020}on\u{0020}the\u{0020}amount\u{0020}of\u{0020}<color=#ffbe32>Stamina</color>\u{0020}consumed.", "0", 105, "0", "0", "0", "体力", "大部分作战都会消耗<color=#ffbe32>体力</color>，在作战成功时根据消耗的<color=#ffbe32>体力</color>领航会得到对应量的经验值。"},
[5003] = {5003, 5, "Experience", 3, "After\u{0020}reaching\u{0020}the\u{0020}<color=#ffbe32>EXP</color>\u{0020}cap\u{0020}for\u{0020}each\u{0020}level,\u{0020}the\u{0020}navigator\u{0020}will\u{0020}level\u{0020}up.\u{0020}As\u{0020}the\u{0020}level\u{0020}increases,\u{0020}the\u{0020}<color=#ffbe32>EXP</color>\u{0020}cap\u{0020}also\u{0020}increases.", "0", 106, "0", "0", "0", "经验值", "每级的<color=#ffbe32>经验值</color>达到上限后就会升到下一级。随着等级的提高，<color=#ffbe32>经验值</color>的上限也会有所提高。"},
[5004] = {5004, 5, "Activity\u{0020}Score", 4, "Completing\u{0020}tasks\u{0020}earns\u{0020}you\u{0020}<color=#ffbe32>Activity\u{0020}Score</color>.\u{0020}There\u{0020}are\u{0020}daily,\u{0020}weekly,\u{0020}and\u{0020}monthly\u{0020}tasks\u{0020}with\u{0020}certain\u{0020}<color=#ffbe32>Activity\u{0020}Score</color>.\u{0020}Once\u{0020}the\u{0020}<color=#ffbe32>Activity\u{0020}Score</color>\u{0020}reach\u{0020}a\u{0020}certain\u{0020}value,\u{0020}you\u{0020}can\u{0020}claim\u{0020}additional\u{0020}rewards.", "0", 107, "0", "0", "0", "活跃积分", "完成任务时会获得<color=#ffbe32>活跃积分</color>。日、周、月三种类的任务都有对应种类的<color=#ffbe32>活跃积分</color>。当<color=#ffbe32>活跃积分</color>达到一定值后，就能够领取额外的奖励。"},
[5005] = {5005, 5, "Commemorative\u{0020}Badges", 5, "Upon\u{0020}completing\u{0020}<color=#ffbe32>achievements</color>\u{0020}or\u{0020}reaching\u{0020}a\u{0020}certain\u{0020}level\u{0020}of\u{0020}collection\u{0020}for\u{0020}each\u{0020}team,\u{0020}you\u{0020}can\u{0020}claim\u{0020}the\u{0020}corresponding\u{0020}<color=#ffbe32>commemorative\u{0020}badges</color>.\u{0020}<color=#ffbe32>Commemorative\u{0020}badges</color>\u{0020}can\u{0020}be\u{0020}displayed\u{0020}on\u{0020}your\u{0020}<color=#ffbe32>profile</color>.", "0", 108, "0", "0", "0", "纪念勋章", "完成<color=#ffbe32>成就</color>或每个部队收集度达到一定程度时就可领取对应的<color=#ffbe32>纪念勋章</color>，<color=#ffbe32>纪念勋章</color>可以展示在个人信息界面中。"},
[5006] = {5006, 5, "Soap\u{0020}Bubbles", 6, "Drivers\u{0020}returning\u{0020}from\u{0020}the\u{0020}battlefield\u{0020}need\u{0020}to\u{0020}wash\u{0020}themselves.\nSoap\u{0020}up\u{0020}the\u{0020}drivers!\u{0020}Touch\u{0020}the\u{0020}screen\u{0020}and\u{0020}follow\u{0020}the\u{0020}planned\u{0020}route\u{0020}to\u{0020}use\u{0020}soap\u{0020}most\u{0020}efficiently.", "0", 109, "0", "0", "0", "肥皂泡泡", "沿着规定好的路线为驾驶员打上肥皂吧！\n正确的路线，能最大效率地利用肥皂。"},
[5007] = {5007, 5, "Capture\u{0020}Aquatic\u{0020}Animals", 7, "Because\u{0020}of\u{0020}the\u{0020}combat\u{0020}in\u{0020}the\u{0020}ocean\u{0020}and\u{0020}rivers,\u{0020}aquatic\u{0020}animals\u{0020}that\u{0020}lived\u{0020}here\u{0020}sometimes\u{0020}get\u{0020}stuck\u{0020}on\u{0020}the\u{0020}drivers.\nWatch\u{0020}for\u{0020}the\u{0020}right\u{0020}moment\u{0020}and\u{0020}tap\u{0020}the\u{0020}screen\u{0020}to\u{0020}help\u{0020}the\u{0020}drivers\u{0020}shake\u{0020}off\u{0020}the\u{0020}animals\u{0020}on\u{0020}them.", "0", 110, "0", "0", "0", "捕捉水生动物", "因为在海洋、河流作战，原本栖息于此的水生动物，偶尔会挂在驾驶员身上。\n看准时机点击屏幕，来帮助驾驶员赶走身上的小动物。"},
[5008] = {5008, 5, "Choice!\u{0020}The\u{0020}Mystery\u{0020}of\u{0020}Skincare", 8, "Choose\u{0020}the\u{0020}most\u{0020}suitable\u{0020}skincare\u{0020}products\u{0020}for\u{0020}the\u{0020}drivers,\u{0020}as\u{0020}drivers\u{0020}from\u{0020}different\u{0020}regions\u{0020}require\u{0020}different\u{0020}skincare\u{0020}products.\nAnswer\u{0020}each\u{0020}question\u{0020}correctly\u{0020}to\u{0020}select\u{0020}the\u{0020}perfect\u{0020}product\u{0020}for\u{0020}the\u{0020}driver.", "0", 111, "0", "0", "0", "抉择！护肤品之谜", "为驾驶员挑选最合适的护肤品，来自不同地区的驾驶员，适用的护肤品也不同。\n答对每道问题，就能为驾驶员选出最合适的那一款。"},
}
return HelpLocalData
